using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using Sps.Apim.SelfServe.Domain.Entities; using Sps.Apim.SelfServe.Infrastructure.Identity;
namespace Sps.Apim.SelfServe.Infrastructure.Persistence.Configurations;
public sealed class ProjectConfiguration:IEntityTypeConfiguration<Project>{public void Configure(EntityTypeBuilder<Project>b){b.ToTable("Projects");b.HasKey(x=>x.Id);b.Property(x=>x.Name).HasMaxLength(200).IsRequired();b.HasIndex(x=>x.Name).IsUnique();}}
public sealed class UserProjectConfiguration:IEntityTypeConfiguration<UserProject>{public void Configure(EntityTypeBuilder<UserProject>b){b.ToTable("UserProjects");b.HasKey(x=>new{x.UserId,x.ProjectId});b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.Project).WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class AuditEventConfiguration:IEntityTypeConfiguration<AuditEvent>{public void Configure(EntityTypeBuilder<AuditEvent>b){b.ToTable("AuditEvents");b.HasKey(x=>x.Id);b.Property(x=>x.EventType).HasMaxLength(100).IsRequired();b.Property(x=>x.Outcome).HasMaxLength(50).IsRequired();b.Property(x=>x.CorrelationId).HasMaxLength(100);b.HasIndex(x=>x.OccurredAtUtc);}}
